"""Linux build for draco_ids.cpp; no CMake, Makefile, git or network needed.

Put this script beside the ORIGINAL draco_ids.cpp previously supplied.
Install prerequisites: python3 -m pip install --user numpy setuptools pybind11
Build: python3 setup_draco_linux.py build_ext --inplace
Or simply: python3 setup_draco_linux.py
Requires a C++17 compiler (g++) and matching Python development headers.
Parallelism: DRACO_BUILD_JOBS=4 (default 2).

The embedded ZIP holds patched Draco 1.5.7 sources from DracoPy 2.1.0,
its original licenses, a change patch, and the fixed build configuration.
It is extracted to _draco_ids_vendor beside this script for inspection.
No installed Draco/DracoPy library is used. Public API stays unchanged.
The payload is source code, not a precompiled platform-specific library.
"""
from pathlib import Path, PurePosixPath
import base64
import hashlib
import io
import os
import sys
import zipfile


def main():
    if not sys.platform.startswith("linux"):
        raise SystemExit("This build script targets Linux.")
    root = Path(__file__).resolve().parent
    os.chdir(root)
    if not (root / "draco_ids.cpp").is_file():
        raise SystemExit("Put draco_ids.cpp in the same directory as this script.")
    try:
        from setuptools import setup
        from pybind11.setup_helpers import Pybind11Extension, build_ext, ParallelCompile
    except ImportError as exc:
        raise SystemExit("Install dependencies first: python3 -m pip install --user numpy setuptools pybind11") from exc

    packed = base64.b64decode(_DRACO_SOURCE_ZIP)
    if hashlib.sha256(packed).hexdigest() != _ZIP_SHA256:
        raise SystemExit("Embedded Draco sources are damaged; download this script again.")
    vendor = root / "_draco_ids_vendor"
    with zipfile.ZipFile(io.BytesIO(packed)) as archive:
        for item in archive.infolist():
            relative = PurePosixPath(item.filename)
            if relative.is_absolute() or ".." in relative.parts:
                raise RuntimeError("Invalid embedded source path")
            path = vendor.joinpath(*relative.parts)
            data = archive.read(item)
            path.parent.mkdir(parents=True, exist_ok=True)
            if not path.is_file() or path.read_bytes() != data:
                path.write_bytes(data)

    sources = ["draco_ids.cpp"] + [
        str(Path("_draco_ids_vendor") / name)
        for name in (vendor / "SOURCES.txt").read_text().splitlines()
    ]
    os.environ.setdefault("CC", "gcc")
    os.environ.setdefault("CXX", "g++")
    ParallelCompile("DRACO_BUILD_JOBS", default=2).install()
    extension = Pybind11Extension(
        "draco_ids",
        sources,
        cxx_std=17,
        include_dirs=[str(vendor / "src")],
        define_macros=[("_FILE_OFFSET_BITS", "64"), ("_LARGEFILE_SOURCE", None)],
        extra_compile_args=["-O3", "-fvisibility=hidden", "-fvisibility-inlines-hidden"],
        depends=[str(p) for p in (vendor / "src").rglob("*.h")],
    )
    if len(sys.argv) == 1:
        sys.argv += ["build_ext", "--inplace"]
    setup(
        name="draco_ids",
        version="1.0.0",
        ext_modules=[extension],
        cmdclass={"build_ext": build_ext},
        packages=[],
        py_modules=[],
    )


